//go:build ignore

package main
import("encoding/json";"go/ast";"go/parser";"go/token";"html";"os";"runtime";"strconv";"unicode";"path/filepath")
func main(){out:="/tmp/weknora-source-location/resources";if len(os.Args)>1{out=os.Args[1]};os.MkdirAll(out,0755);f,e:=parser.ParseFile(token.NewFileSet(),runtime.GOROOT()+"/src/html/entity.go",nil,0);if e!=nil{panic(e)};entities:=map[string]string{};ast.Inspect(f,func(n ast.Node)bool{if kv,ok:=n.(*ast.KeyValueExpr);ok{if s,ok:=kv.Key.(*ast.BasicLit);ok&&s.Kind==token.STRING{key,e:=strconv.Unquote(s.Value);if e==nil{if val:=html.UnescapeString("&"+key);val!="&"+key{entities[key]=val}}}};return true});b,_:=json.Marshal(entities);os.WriteFile(filepath.Join(out,"go-html-entities.json"),b,0600);ranges:=map[string][][3]uint32{};for key,t:=range map[string]*unicode.RangeTable{"letter":unicode.Letter,"digit":unicode.Digit}{for _,r:=range t.R16{ranges[key]=append(ranges[key],[3]uint32{uint32(r.Lo),uint32(r.Hi),uint32(r.Stride)})};for _,r:=range t.R32{ranges[key]=append(ranges[key],[3]uint32{r.Lo,r.Hi,r.Stride})}};for r:=rune(0);r<=unicode.MaxRune;r++{if lower:=unicode.ToLower(r);lower!=r{ranges["lower"]=append(ranges["lower"],[3]uint32{uint32(r),uint32(lower),0})}};b,_=json.Marshal(ranges);os.WriteFile(filepath.Join(out,"go-source-unicode.json"),b,0600)}
